{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "https://raw.githubusercontent.com/zach-blumenfeld/aip-spec/v0.6a1/assets/procedure.schema.json",
 "title": "Procedure",
 "description": "An execution graph of typed steps run by an AIP server with the client in the loop. Step kinds are `decision` (SystemOne questions answered by a structured decision model), `execution` (a script under scripts/), `client_task` (templated work the client performs itself), `router` (server-side branching on a value the client chose), and `end` (the procedure's result). The first step in `steps` is the start; its `inputs` are what the client supplies. Edges are `inputs_to` by step name. Every runnable step declares the keys it reads as `inputs`; execution and client_task steps declare the keys they add as `outputs`, and a decision's outputs are its question names. Every key is produced by exactly one step, so the state only grows.",
 "aip": {
  "spec": "https://github.com/zach-blumenfeld/aip-spec/tree/v0.6a1",
  "version": "0.6a1"
 },
 "additionalProperties": false,
 "properties": {
  "purpose": {
   "description": "What the procedure encapsulates as a coherent unit of work: the scope it covers and what it adds beyond general agent knowledge. One short paragraph.",
   "title": "Purpose",
   "type": "string"
  },
  "trigger_when": {
   "description": "Conditions under which the agent should consider this skill. Mixed granularity expected: immediate invocation triggers alongside broader applicability contexts belong in the same list.",
   "items": {
    "type": "string"
   },
   "minItems": 1,
   "title": "Trigger When",
   "type": "array"
  },
  "do_not_use_when": {
   "description": "Conditions under which the agent should NOT use this skill: explicit non-purposes that pair with trigger_when to sharpen activation.",
   "items": {
    "type": "string"
   },
   "title": "Do Not Use When",
   "type": "array"
  },
  "requires": {
   "anyOf": [
    {
     "$ref": "#/$defs/Requires"
    },
    {
     "type": "null"
    }
   ],
   "default": null,
   "description": "The environment the scripts need: interpreter and minimum version, Python packages, other tools. Required when the procedure has execution steps."
  },
  "steps": {
   "description": "The nodes of the execution graph. The first step is the start and must be runnable (decision, execution, or client_task). Exactly one step has kind `end`. Every runnable step names the node that receives its output via `inputs_to`; routers name theirs via `branches`. The validator checks that names are unique, every reference resolves, every step is reachable from the start, every step can reach the end, every consumed key is produced on every path to its consumer or declared on the start step, every key has exactly one producer, a procedure with execution steps declares `requires` and launches each script with its interpreter or one of its tools, and every referenced asset, reference, and script exists on disk.",
   "items": {
    "discriminator": {
     "mapping": {
      "client_task": "#/$defs/ClientTaskStep",
      "decision": "#/$defs/DecisionStep",
      "end": "#/$defs/EndStep",
      "execution": "#/$defs/ExecutionStep",
      "router": "#/$defs/RouterStep"
     },
     "propertyName": "kind"
    },
    "oneOf": [
     {
      "$ref": "#/$defs/DecisionStep"
     },
     {
      "$ref": "#/$defs/ExecutionStep"
     },
     {
      "$ref": "#/$defs/ClientTaskStep"
     },
     {
      "$ref": "#/$defs/RouterStep"
     },
     {
      "$ref": "#/$defs/EndStep"
     }
    ]
   },
   "minItems": 2,
   "title": "Steps",
   "type": "array"
  },
  "anti_patterns": {
   "description": "Common mistakes the procedure steers the agent away from. Concrete corrections to errors the agent would otherwise make.",
   "items": {
    "type": "string"
   },
   "title": "Anti Patterns",
   "type": "array"
  }
 },
 "required": [
  "purpose",
  "trigger_when",
  "steps"
 ],
 "type": "object"
}

