def run(script_path: str, json_path: str, dot_path: str) -> Dict[str, Any]:
    """Parse the script, write JSON + DOT, and return a validation report."""
    with open(script_path, "r", encoding="utf-8") as f:
        graph = build_graph(f.read())
    data = graph.to_dict()
