        "node_count": len(data["nodes"]),
        "edge_count": len(data["edges"]),
        "choice_node_count": sum(1 for n in data["nodes"] if n["type"] == "choice"),
        "end_edge_count": sum(1 for e in data["edges"] if e["to"] == END_ID),
        "errors": errors,
